limit = int(input())
for i in range(1, limit + 1):
    if i % 15 == 0:
        print('fizzbuzz')
    elif i % 3 == 0:
        print('fizz')
    elif i % 5 == 0:
        print('buzz')
    else:
        print(i)

n = int(input())
count = {}
for _ in range(n):
    u = input()
    count[u] = count.get(u, 0) + 1
for u, c in sorted(count.items(), key=lambda kv: (-kv[1], kv[0])):
    print(c, u)

n = int(input())
parent = {}
for _ in range(n):
    c, p = input().split()
    parent[c] = p
cur = input().strip()
while cur != '-':
    print(cur)
    cur = parent[cur]

